import { describe, expect, it } from 'vitest';
import { preprocessMdxFragmentCode } from './preprocessMdxFragmentCode.js';
const wrap = (body) => `{true ? <MDX>\n${body}\n</MDX> : null}`;
describe('preprocessMdxFragmentCode', () => {
    it('escapes < > { } inside a fence inside <MDX>', () => {
        const out = preprocessMdxFragmentCode(wrap('```bash\n<root>/{arch}/app.vpkg\n```'));
        expect(out).toBe(wrap('```bash\n&lt;root&gt;/&#123;arch&#125;/app.vpkg\n```'));
    });
    it('escapes inline code inside <MDX>', () => {
        const out = preprocessMdxFragmentCode(wrap('run `mint <cmd>` and `a{b}` now'));
        expect(out).toBe(wrap('run `mint &lt;cmd&gt;` and `a&#123;b&#125;` now'));
    });
    it('leaves prose and JSX inside <MDX> alone', () => {
        const src = wrap('a <b>bold</b> word and a {expr} stay');
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('leaves fences and inline code outside <MDX> alone', () => {
        const src = 'x\n\n```bash\n<root>/{arch}\n```\n\nrun `a <b>` now';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('does not treat <MDX> inside a page-level fence as an opener', () => {
        const src = '```mdx\n<MDX>\n\n# example\n</MDX>\n```\n\n`<x>` after';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('is idempotent and never escapes &', () => {
        const src = wrap('```bash\n<a> and &lt;b&gt; and &amp;\n```');
        const once = preprocessMdxFragmentCode(src);
        expect(once).toBe(wrap('```bash\n&lt;a&gt; and &lt;b&gt; and &amp;\n```'));
        expect(preprocessMdxFragmentCode(once)).toBe(once);
    });
    it('a </MDX> inside a fence is escaped and does not close the block', () => {
        const out = preprocessMdxFragmentCode(wrap('```\n</MDX>\n```\n\n`<after>`'));
        expect(out).toBe(wrap('```\n&lt;/MDX&gt;\n```\n\n`&lt;after&gt;`'));
    });
    it('handles block-level <MDX> and nested <MDX> bodies', () => {
        const src = '<MDX>\n\n```txt\n<x>\n```\n\n<MDX>\n\n`{y}`\n</MDX>\n</MDX>';
        expect(preprocessMdxFragmentCode(src)).toBe('<MDX>\n\n```txt\n&lt;x&gt;\n```\n\n<MDX>\n\n`&#123;y&#125;`\n</MDX>\n</MDX>');
    });
    it('keeps fence markers, info strings, and indentation untouched', () => {
        const src = wrap('  ```bash filename="a.sh"\n  <x>\n  ```');
        expect(preprocessMdxFragmentCode(src)).toBe(wrap('  ```bash filename="a.sh"\n  &lt;x&gt;\n  ```'));
    });
    it('an `<MDX>` mention in root inline code does not poison later root code', () => {
        const src = 'Use `<MDX>` to branch.\n\n```bash\n<root>/{arch}\n```\n\nrun `a <b>` now';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('escapes inline code on the same line as the <MDX> tags', () => {
        const out = preprocessMdxFragmentCode('{true ? <MDX>run `mint <cmd>` now</MDX> : null}');
        expect(out).toBe('{true ? <MDX>run `mint &lt;cmd&gt;` now</MDX> : null}');
    });
    it('only spans between the tags are escaped on a shared line', () => {
        const out = preprocessMdxFragmentCode('`a<b` <MDX>`c<d`</MDX> `e<f`');
        expect(out).toBe('`a<b` <MDX>`c&lt;d`</MDX> `e<f`');
    });
    it('a tag inside an inline code span within a fragment is not counted', () => {
        const out = preprocessMdxFragmentCode(wrap('mention `</MDX>` here\n\n`x<y`'));
        expect(out).toBe(wrap('mention `&lt;/MDX&gt;` here\n\n`x&lt;y`'));
    });
    it('a complete <MDX> example inside a fragment fence is escaped, not parsed', () => {
        const out = preprocessMdxFragmentCode(wrap('```mdx\n<MDX>\n# hi\n</MDX>\n```\n\n`x<y`'));
        expect(out).toBe(wrap('```mdx\n&lt;MDX&gt;\n# hi\n&lt;/MDX&gt;\n```\n\n`x&lt;y`'));
    });
    it('a tag inside a string literal does not poison later root code', () => {
        // A lone opener in a string used to leave the scanner "inside" a fragment for the rest of
        // the document, escaping root-level code that nothing would ever decode.
        const src = '{label("<MDX>")} intro\n\n```bash\n<root>/{arch}\n```\n\nrun `a <b>` now';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('a balanced pair inside a string literal escapes nothing on the line', () => {
        const src = '{t("<MDX> `a<b` </MDX>")} and `x<y` after';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('a tag inside an attribute value is not counted', () => {
        const src = '<Card title="<MDX>">x</Card>\n\n`code <a>` span';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
    it('returns input unchanged when there is no <MDX>', () => {
        const src = '# Title\n\n```bash\n<root>\n```';
        expect(preprocessMdxFragmentCode(src)).toBe(src);
    });
});
